with open('rewrite_paper.py', 'r', encoding='utf-8') as f:
    lines = f.readlines()

# Find all lines where an ASCII \" appears inside what should be content
for i, line in enumerate(lines):
    stripped = line.strip()
    if not stripped:
        continue
    # Count unescaped double quotes
    count = 0
    in_str = False
    for ch in stripped:
        if ch == '\"':
            count += 1
    # If we have an odd pattern or multiple pairs inside Chinese content
    if '\u201c' in stripped or '\u201d' in stripped:
        continue  # Already fixed
    for j, ch in enumerate(stripped):
        if ch == '\"' and j > 0 and ord(stripped[j-1]) > 0x4e00:
            print(f'Line {i+1}: {stripped[:80]}')
            break
" 2>&1 | head -30
