root = etree.fromstring(xml)
w = '{http://schemas.openxmlformats.org/wordprocessingml/2006/main}'

# Collect orange text by paragraph context
current_orange = []
orange_groups = {}

for run in root.iter(w + 'r'):
    rpr = run.find(w + 'rPr')
    color_val = '000000'
    if rpr is not None:
        color = rpr.find(w + 'color')
        if color is not None:
            color_val = color.get(w + 'val', '000000')

    texts = []
    for t in run.iter(w + 't'):
        if t.text:
            texts.append(t.text)
    text = ''.join(texts)

    if color_val == 'F39800' and text.strip():
        current_orange.append(text.strip())
    else:
        if current_orange:
            combined = ''.join(current_orange)
            if combined not in orange_groups:
                orange_groups[combined] = 1
            else:
                orange_groups[combined] += 1
            current_orange = []

if current_orange:
    combined = ''.join(current_orange)
    orange_groups[combined] = 1

# Also check gray
print('=== 🟠 橙色文本 ===')
for text in sorted(orange_groups, key=len, reverse=True)[:5]:
    print(f'  [{len(text)}字] {text[:150]}')
    print()

# Check gray text
gray_texts = []
current_gray = []
for run in root.iter(w + 'r'):
    rpr = run.find(w + 'rPr')
    color_val = '000000'
    if rpr is not None:
        color = rpr.find(w + 'color')
        if color is not None:
            color_val = color.get(w + 'val', '000000')
    texts = []
    for t in run.iter(w + 't'):
        if t.text:
            texts.append(t.text)
    text = ''.join(texts)
    if color_val == 'B0B0B0' and text.strip():
        current_gray.append(text.strip())
    else:
        if current_gray:
            gray_texts.append(''.join(current_gray))
            current_gray = []

print('=== ⚪ 灰色文本 (前10) ===')
for g in gray_texts[:10]:
    print(f'  [{len(g)}字] {g[:80]}')
" 2>&1
